// Fork of https://shadertoy.com/view/MdfcRS

// -6ch by Shane

float N( vec2 f ) {                                      // value noise
    vec2 p = floor(f); f -= p;
    f = f*f*(3. - f-f);    
    #define H(i,j)  fract(sin(1e3*dot(p+vec2(i,j),vec2(1,57)))*4e3)    
    return mix(mix( H(0,0), H(1,0), f.x),  
               mix( H(0,1), H(1,1), f.x), f.y);
}

void mainImage( out vec4 O, vec2 U )
{
    U = U*8./iResolution.y + iTime;
    float n =  ( N(U) + N(U+11.5) ) * N(U/3.7) /.1,      // heigth field
          v = sin(3.14*n);                               // for isovalues

    O = smoothstep(-1.,1., .7*abs(v)/fwidth(v))          // isovalues
      * (.8+.2*cos(.4*ceil(n)+1.5+vec4(0,21,23,0)));     // color scheme (desaturated hue)
}
